    n = len(grid) // 3
    out = []
    for i in range(n):
        row = []
        for j in range(n):
            tile = [grid[3*i+x][3*j+y] for x in range(3) for y in range(3)]
            counts = {}
            for value in tile:
                if value != 5:
                    counts[value] = counts.get(value, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 5)
        out.append(row)
